const bind:any = useGesture({
	onDragStart: () => {
		setStartRotation(rotation);
	},
	//x 포지션에 따라 newRotation을 만듬.
	onDrag: ({ movement: [x], dragging }) => {
		const newRotation = Math.max(-0.35, Math.min(0.35, startRotation + x / 300));
		setRotation(newRotation);
	}
}

