// 별 수 나누기
const calculateStarScore = (clearTimer: number): StarScore => {
	if (clearTimer <= 0) {
	  return 0;
  } else if (clearTimer <= 10) {
	  return 0;
  } else if (clearTimer <= 30) {
	  return 1;
  } else if (clearTimer <= 80) {
		return 2;
  } else {
	  return 3;
  }
};

